import subprocess
result = subprocess.run(['pdftotext', '-layout', 'main.pdf', '/dev/stdout'], capture_output=True, text=True)
text = result.stdout
pages = text.split('\f')
for i, page in enumerate(pages):
    if 'References' in page:
        # Check if this is the References heading
        for line in page.split('\n'):
            if 'References' in line and len(line.strip()) < 30:
                print(f"Page {i+1}: {line.strip()}")
                break
    if 'Limitation' in page:
        for line in page.split('\n'):
            if 'Limitation' in line and len(line.strip()) < 30:
                print(f"Page {i+1}: {line.strip()}")
                break
    if 'Appendix' in page or 'appendix' in page:
        for line in page.split('\n'):
            stripped = line.strip()
            if ('Appendix' in stripped or 'appendix' in stripped) and len(stripped) < 40:
                print(f"Page {i+1}: {stripped}")
                break
EOF

